import { DatePipe, DecimalPipe } from '@angular/common';
import { Component, OnInit, inject, signal } from '@angular/core';
import { RouterLink } from '@angular/router';

import { Page, errorMessage } from '../../core/api';
import { hasRole } from '../../core/keycloak';
import { Invoice } from './payment.models';
import { PaymentsService } from './payments.service';

/** Invoices (generated by payment-service, read-only). CLIENT: own invoices; AGENT/ADMIN: all. */
@Component({
  selector: 'app-invoice-list',
  imports: [RouterLink, DatePipe, DecimalPipe],
  template: `
    @if (error()) { <div class="alert error">{{ error() }}</div> }
    @if (page(); as page) {
      @if (page.items.length === 0) {
        <div class="card muted">Aucune facture pour le moment.</div>
      } @else {
        <table>
          <thead>
            <tr>
              <th>Numéro</th><th>Date</th><th>Réservation</th>
              @if (staff) { <th>Client</th> }
              <th>Lignes</th><th class="num">Total</th><th></th>
            </tr>
          </thead>
          <tbody>
            @for (inv of page.items; track inv.id) {
              <tr>
                <td><strong>{{ inv.number }}</strong></td>
                <td>{{ inv.issuedAt | date: 'dd/MM/yyyy' }}</td>
                <td><code [title]="inv.reservationId">{{ inv.reservationId.slice(0, 8) }}</code></td>
                @if (staff) { <td><code [title]="inv.userId">{{ inv.userId.slice(0, 8) }}</code></td> }
                <td>{{ inv.lines.length }}</td>
                <td class="num">{{ inv.total | number: '1.3-3' }} {{ inv.currency }}</td>
                <td><a class="button small" [routerLink]="inv.id">Voir</a></td>
              </tr>
            }
          </tbody>
        </table>
        <div class="pager">
          <span class="muted">{{ page.total }} facture(s) · page {{ page.page + 1 }}</span>
          <button type="button" [disabled]="page.page === 0" (click)="load(page.page - 1)">Précédent</button>
          <button type="button" [disabled]="(page.page + 1) * page.size >= page.total" (click)="load(page.page + 1)">
            Suivant
          </button>
        </div>
      }
    } @else if (!error()) {
      <p class="muted">Chargement…</p>
    }
  `,
})
export class InvoiceList implements OnInit {
  private readonly api = inject(PaymentsService);
  protected readonly staff = hasRole('AGENT', 'ADMIN');
  protected readonly page = signal<Page<Invoice> | null>(null);
  protected readonly error = signal<string | null>(null);

  ngOnInit(): void {
    this.load(0);
  }

  protected load(pageIndex: number): void {
    this.api.listInvoices(pageIndex).subscribe({
      next: (page) => this.page.set(page),
      error: (err) => this.error.set(errorMessage(err)),
    });
  }
}
